			const fit = fitCanvas(host, canvas, 960, 600);
			if (fit === null) throw new Error("dsh-minigames: hole needs a 2d canvas context");
			const ctx = fit.ctx;
			const seed = dailySeed();
			let round = 0;
			let state = createHole(seed, round);
			let running = false;
			let lastScore = -1;
			let acc = 0;
			let clock = 0;
			const cam = {
				x: state.holes[0].x,
				y: state.holes[0].y
			};
