		/**
		* 三次贝塞尔求值（de Casteljau 展开），t∈[0,1]。
		* @param seg - 曲线段（8 数组）。
		* @param t - 参数。
		* @returns 曲线上的点。
		*/
		function bezierAt(seg, t) {
			const x0 = seg[0], y0 = seg[1], cx1 = seg[2], cy1 = seg[3], cx2 = seg[4], cy2 = seg[5], x3 = seg[6], y3 = seg[7];
			const u = 1 - t;
			const a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
			return {
				x: a * x0 + b * cx1 + c * cx2 + d * x3,
				y: a * y0 + b * cy1 + c * cy2 + d * y3
			};
		}
		/**
		* 装配某一关的轨道：归一化贝塞尔链 → 像素折线 + 弧长表 + 中点检查点。
		* @param level - 关卡号（1 起）。
		* @returns 轨道数据。
		*/
		function buildTrack(level) {
			const spec = LEVEL_SPECS[Math.min(5, Math.max(1, Math.floor(level))) - 1];
			const points = [];
			spec.segs.forEach((seg, i) => {
				for (let k = i === 0 ? 0 : 1; k <= 28; k += 1) {
					const p = bezierAt(seg, k / 28);
					points.push({
						x: p.x * 640,
						y: p.y * 440
					});
				}
			});
			const cumLen = [0];
			for (let i = 1; i < points.length; i += 1) {
				const a = points[i - 1], b = points[i];
				cumLen.push(cumLen[i - 1] + Math.hypot(b.x - a.x, b.y - a.y));
			}
			return {
				points,
				cumLen,
				totalLen: cumLen[cumLen.length - 1],
				checkpoint: points[Math.floor(points.length / 2)],
				end: points[points.length - 1],
				railR: spec.railR,
				holeR: spec.holeR
			};
		}
		/**
		* 点到线段的最小距离（投影裁剪到端点）。
		* @param px - 被测点 x。
		* @param py - 被测点 y。
		* @param ax - 线段端点 A x。
		* @param ay - 线段端点 A y。
		* @param bx - 线段端点 B x。
		* @param by - 线段端点 B y。
		* @returns 欧氏最短距离。
		*/
		function pointSegmentDistance(px, py, ax, ay, bx, by) {
			const dx = bx - ax, dy = by - ay;
			const len2 = dx * dx + dy * dy;
			let t = 0;
			if (len2 > 0) t = ((px - ax) * dx + (py - ay) * dy) / len2;
			t = Math.max(0, Math.min(1, t));
			return Math.hypot(px - (ax + dx * t), py - (ay + dy * t));
		}
		/**
		* 环心到轨道中心折线的最小距离。
		* @param track - 轨道。
		* @param x - 环心 x。
		* @param y - 环心 y。
		* @returns 最小距离 px。
		*/
		function minDistanceToTrack(track, x, y) {
			let best = Infinity;
			const pts = track.points;
			for (let i = 1; i < pts.length; i += 1) {
				const d = pointSegmentDistance(x, y, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);
				if (d < best) best = d;
			}
			return best;
		}
		/**
		* 该位置的电环是否触电：环沿碰到金属轨，即 d + 轨半径 ≥ 环孔半径。
		* @param track - 轨道。
		* @param x - 环心 x。
		* @param y - 环心 y。
		* @returns true 表示触电。
		*/
		function isShocked(track, x, y) {
			return minDistanceToTrack(track, x, y) + track.railR >= track.holeR;
		}
		/**
		* 装配某一关的初始字段：轨道、环归位、计时与进度清零、开局保护。
		* @param state - 目标状态（就地更新）。
		* @param level - 关卡号。
		*/
		function enterLevel(state, level) {
			state.level = level;
			state.track = buildTrack(level);
			const start = state.track.points[0];
			state.ringX = start.x;
			state.ringY = start.y;
			state.targetX = start.x;
			state.targetY = start.y;
			state.respawnX = start.x;
			state.respawnY = start.y;
			state.levelMs = 0;
			state.acc = 0;
			state.armed = false;
			state.aimMoved = false;
			state.graceMs = 500;
			state.checkpointTaken = false;
			state.progress = 0;
		}
		/**
		* 新开一局（无随机源，同参数轨迹完全一致）。
		* @param startLevel - 起始关卡（1..5，越界收敛）。
		* @param bestMs - 跨局保留的最佳通关时间（可省略）。
		* @returns 初始状态。
		*/
		function createSteadyHand(startLevel = 1, bestMs = null) {
			const state = {
				t: 0,
				levelMs: 0,
				score: 0,
				lives: 3,
				level: 1,
				ringX: 0,
				ringY: 0,
				targetX: 0,
				targetY: 0,
				acc: 0,
				graceMs: 0,
				flashMs: 0,
				shakeMs: 0,
				respawnX: 0,
				respawnY: 0,
				checkpointTaken: false,
				armed: false,
				aimMoved: false,
				progress: 0,
				bestMs,
				track: buildTrack(1),
				events: [],
				over: false,
				complete: false
			};
			enterLevel(state, Math.min(5, Math.max(1, Math.floor(startLevel))));
			return state;
		}
		/**
		* 指针移动：仅更新追踪目标，环在后续 step 中限速追赶。
		* @param state - 目标状态。
		* @param x - 指针逻辑坐标 x。
		* @param y - 指针逻辑坐标 y。
		*/
		function setPointer(state, x, y) {
			state.targetX = x;
			state.targetY = y;
		}
		/**
		* 过关得分：基础分 + 时间分（每 100ms 递减 1 分，下限 0）。
		* @param levelMs - 本关用时 ms。
		* @returns 该关得分。
		*/
		function levelScore(levelMs) {
			return 100 + Math.max(0, 500 - Math.floor(levelMs / 100));
		}
		/** 触电处理：-1 命、红闪震屏，进入重新就位阶段——环留在触电处，
		* 玩家必须把环带回重生点标记重新就位（不计时不判定）才继续。 */
		function shock(state) {
			state.lives -= 1;
			state.flashMs = 380;
			state.shakeMs = 420;
			state.graceMs = 500;
			const sx = state.ringX, sy = state.ringY;
			state.armed = false;
			state.acc = 0;
			state.events.push({
				type: "shock",
				x: sx,
				y: sy
			});
			if (state.lives <= 0) {
				state.lives = 0;
				state.over = true;
			}
		}
		/**
		* 推进一帧：固定 8ms 子步内环向指针限速移动，逐步判定终点、检查点、
		* 触电；触电立即处理并回到重生点。事件写入 state.events，调用方每帧
		* 消费后由本函数在下一帧开头清空。
		* @param state - 目标状态。
		* @param dtMs - 帧间隔 ms。
		*/
		function stepSteadyHand(state, dtMs) {
			state.events.length = 0;
			if (state.over) return;
			state.t += dtMs;
			if (state.armed) state.levelMs += dtMs;
			if (state.flashMs > 0) state.flashMs = Math.max(0, state.flashMs - dtMs);
			if (state.shakeMs > 0) state.shakeMs = Math.max(0, state.shakeMs - dtMs);
			if (state.graceMs > 0) state.graceMs = Math.max(0, state.graceMs - dtMs);
			state.acc += dtMs;
			const track = state.track;
			while (state.acc >= 8) {
				state.acc -= 8;
				const dx = state.targetX - state.ringX;
				const dy = state.targetY - state.ringY;
				const dist = Math.hypot(dx, dy);
				const stepLen = RING_SPEED * 8 / 1e3;
				if (dist > 1e-9) {
					const move = Math.min(stepLen, dist);
					state.ringX += dx / dist * move;
					state.ringY += dy / dist * move;
				}
				if (!state.armed) {
					const rx = state.respawnX, ry = state.respawnY;
					const aimDist = Math.hypot(state.targetX - rx, state.targetY - ry);
					if (aimDist > 60) state.aimMoved = true;
					if (Math.hypot(state.ringX - rx, state.ringY - ry) <= 22 && state.aimMoved && aimDist <= 30) {
						state.armed = true;
						state.events.push({ type: "armed" });
					}
					continue;
				}
				if (Math.hypot(state.ringX - track.end.x, state.ringY - track.end.y) <= 26) {
					const gained = levelScore(state.levelMs);
					state.score += gained;
					if (state.bestMs === null || state.levelMs < state.bestMs) state.bestMs = state.levelMs;
					state.events.push({
						type: "clear",
						level: state.level,
						ms: state.levelMs,
						gained
					});
					if (state.level >= 5) {
						state.complete = true;
						state.over = true;
						state.events.push({
							type: "complete",
							score: state.score
						});
						return;
					}
					enterLevel(state, state.level + 1);
					return;
				}
				if (Math.hypot(state.ringX - track.checkpoint.x, state.ringY - track.checkpoint.y) <= 32) {
					if (!state.checkpointTaken) {
						state.checkpointTaken = true;
						state.events.push({ type: "checkpoint" });
					}
					state.respawnX = track.checkpoint.x;
					state.respawnY = track.checkpoint.y;
				} else if (state.graceMs <= 0 && isShocked(track, state.ringX, state.ringY)) {
					shock(state);
					if (state.over) return;
				}
				let bi = 0, bd = Infinity;
				for (let i = 0; i < track.points.length; i += 1) {
					const p = track.points[i];
					const d = (p.x - state.ringX) * (p.x - state.ringX) + (p.y - state.ringY) * (p.y - state.ringY);
					if (d < bd) {
						bd = d;
						bi = i;
					}
				}
				const frac = track.cumLen[bi] / track.totalLen;
				if (frac > state.progress) state.progress = frac;
			}
		}
		//#endregion
		//#region src/client/games/steadyhand/render.ts
		const RAIL_DARK = "#232a3d";
		const RAIL_BODY = "#3d4d70";
		const RAIL_CORE = "#cfe8ff";
		const CURRENT_COLOR = "#7dcfff";
		const ISLAND_COLOR = "#e0af68";
		const END_COLOR = "#9ece6a";
		const START_COLOR = "#7dcfff";
		const RING_COLOR = "#e2e2ee";
		const TRACE_COLOR = "rgba(56,66,96,0.5)";
		const PAD_COLOR = "rgba(80,94,130,0.45)";
		const particles = createParticles();
		/** 确定性伪随机（电路板装饰纹路用，与逻辑无关）。 */
		function decor(seed) {
			let t = seed >>> 0;
			t = Math.imul(t ^ t >>> 15, t | 1);
			t ^= t + Math.imul(t ^ t >>> 7, t | 61);
			return ((t ^ t >>> 14) >>> 0) / 4294967296;
		}
		/**
		* 深色电路板背景：共享渐变底 + 细网格 + 若干确定性水平走线与焊盘。
		* @param ctx - 画布上下文。
		* @param t - 动画时钟 ms（走线电流微光流动）。
		*/
		function drawCircuitBoard(ctx, t) {
			drawBackground(ctx, 640, 440);
			ctx.strokeStyle = TRACE_COLOR;
			ctx.lineWidth = 1;
			ctx.beginPath();
			for (let x = 20; x < 640; x += 40) {
				ctx.moveTo(x, 0);
				ctx.lineTo(x, 440);
			}
			for (let y = 20; y < 440; y += 40) {
				ctx.moveTo(0, y);
				ctx.lineTo(640, y);
			}
			ctx.stroke();
			for (let i = 0; i < 6; i += 1) {
				const y = 60 + decor(i * 97 + 13) * 320;
				const x0 = decor(i * 31 + 7) * 640 * .5;
				const x1 = 320 + decor(i * 57 + 29) * 640 * .5;
				ctx.strokeStyle = TRACE_COLOR;
				ctx.lineWidth = 2;
				ctx.beginPath();
				ctx.moveTo(x0, y);
				ctx.lineTo(x1, y);
				ctx.stroke();
				ctx.fillStyle = PAD_COLOR;
				for (const px of [x0, x1]) {
					ctx.beginPath();
					ctx.arc(px, y, 3.5, 0, Math.PI * 2);
					ctx.fill();
				}
				const span = x1 - x0;
				const ph = (t / 40 + i * 300) % (span + 120) - 60;
				ctx.strokeStyle = "rgba(122,162,247,0.25)";
				ctx.lineWidth = 2;
				ctx.beginPath();
				ctx.moveTo(Math.max(x0, x0 + ph - 40), y);
				ctx.lineTo(Math.min(x1, x0 + ph + 40), y);
				ctx.stroke();
			}
		}
		/**
		* 画金属轨：外层暗晕 + 轨身双层描边 + 中心亮线 + 流动电流虚线。
		* @param ctx - 画布上下文。
		* @param track - 轨道。
		* @param t - 动画时钟 ms（虚线相位）。
		*/
		function drawRail(ctx, track, t) {
			const pts = track.points;
			const path = () => {
				ctx.beginPath();
				ctx.moveTo(pts[0].x, pts[0].y);
				for (let i = 1; i < pts.length; i += 1) ctx.lineTo(pts[i].x, pts[i].y);
			};
			ctx.lineJoin = "round";
			ctx.lineCap = "round";
			glow(ctx, RAIL_BODY, 16);
			ctx.strokeStyle = RAIL_DARK;
			ctx.lineWidth = track.railR * 2 + 12;
			path();
			ctx.stroke();
			noGlow(ctx);
			ctx.strokeStyle = RAIL_BODY;
			ctx.lineWidth = track.railR * 2;
			path();
			ctx.stroke();
			glow(ctx, RAIL_CORE, 8);
			ctx.strokeStyle = RAIL_CORE;
			ctx.lineWidth = 2;
			path();
			ctx.stroke();
			noGlow(ctx);
			ctx.setLineDash([12, 16]);
			ctx.lineDashOffset = -(t / 12) % 28;
			glow(ctx, CURRENT_COLOR, 10);
			ctx.strokeStyle = CURRENT_COLOR;
			ctx.lineWidth = 3;
			path();
			ctx.stroke();
			noGlow(ctx);
			ctx.setLineDash([]);
		}
		/**
		* 画终点标记：绿色光环 + 内点。
		* @param ctx - 画布上下文。
		* @param track - 轨道。
		* @param t - 动画时钟 ms。
		*/
		function drawEnd(ctx, track, t) {
			const pulse = 1 + Math.sin(t / 260) * .12;
			glow(ctx, END_COLOR, 14);
			ctx.strokeStyle = END_COLOR;
			ctx.lineWidth = 3;
			ctx.beginPath();
			ctx.arc(track.end.x, track.end.y, 26 * pulse * .8, 0, Math.PI * 2);
			ctx.stroke();
			ctx.fillStyle = END_COLOR;
			ctx.beginPath();
			ctx.arc(track.end.x, track.end.y, 5, 0, Math.PI * 2);
			ctx.fill();
			noGlow(ctx);
		}
		/**
		* 画中段安全岛：金色呼吸光环 + 半透明填充；已存档后常亮。
		* @param ctx - 画布上下文。
		* @param state - 当前状态。
		*/
		function drawIsland(ctx, state) {
			const { checkpoint } = state.track;
			const r = 32 * (1 + Math.sin(state.t / 320) * .1);
			const color = state.checkpointTaken ? END_COLOR : ISLAND_COLOR;
			ctx.fillStyle = state.checkpointTaken ? "rgba(158,206,106,0.10)" : "rgba(224,175,104,0.10)";
			ctx.beginPath();
			ctx.arc(checkpoint.x, checkpoint.y, r, 0, Math.PI * 2);
			ctx.fill();
			glow(ctx, color, 12);
			ctx.strokeStyle = color;
			ctx.lineWidth = 2;
			ctx.beginPath();
			ctx.arc(checkpoint.x, checkpoint.y, r, 0, Math.PI * 2);
			ctx.stroke();
			noGlow(ctx);
		}
		/**
		* 画电环：环体 + 指针光晕 + 环到指针的牵引细线。
		* @param ctx - 画布上下文。
		* @param state - 当前状态。
		*/
		function drawRing(ctx, state) {
			const holeR = state.track.holeR;
			ctx.strokeStyle = "rgba(226,226,238,0.15)";
			ctx.lineWidth = 1;
			ctx.beginPath();
			ctx.moveTo(state.ringX, state.ringY);
			ctx.lineTo(state.targetX, state.targetY);
			ctx.stroke();
			glow(ctx, THEME.accents[1], 10);
			ctx.fillStyle = "rgba(187,154,247,0.35)";
			ctx.beginPath();
			ctx.arc(state.targetX, state.targetY, 5, 0, Math.PI * 2);
			ctx.fill();
			noGlow(ctx);
			const danger = state.graceMs > 0;
			glow(ctx, danger ? THEME.bad : CURRENT_COLOR, 14);
			ctx.strokeStyle = danger ? THEME.bad : RING_COLOR;
			ctx.lineWidth = 4;
			ctx.beginPath();
			ctx.arc(state.ringX, state.ringY, holeR, 0, Math.PI * 2);
			ctx.stroke();
			noGlow(ctx);
			ctx.strokeStyle = "rgba(226,226,238,0.5)";
			ctx.lineWidth = 1;
			ctx.beginPath();
			ctx.moveTo(state.ringX - 6, state.ringY);
			ctx.lineTo(state.ringX + 6, state.ringY);
			ctx.moveTo(state.ringX, state.ringY - 6);
			ctx.lineTo(state.ringX, state.ringY + 6);
			ctx.stroke();
		}
		/**
		* 画触电闪电链：从环到轨道最近点的锯齿折线（纯视觉随机）。
		* @param ctx - 画布上下文。
		* @param state - 当前状态。
		*/
		function drawLightning(ctx, state) {
			if (state.flashMs <= 0) return;
			const alpha = state.flashMs / 380;
			let bx = 0, by = 0, bd = Infinity;
			for (const p of state.track.points) {
				const d = Math.hypot(p.x - state.ringX, p.y - state.ringY);
				if (d < bd) {
					bd = d;
					bx = p.x;
					by = p.y;
				}
			}
			ctx.globalAlpha = alpha;
			glow(ctx, THEME.bad, 12);
			ctx.strokeStyle = THEME.bad;
			ctx.lineWidth = 2;
			for (let bolt = 0; bolt < 3; bolt += 1) {
				ctx.beginPath();
				ctx.moveTo(state.ringX, state.ringY);
				const segsN = 5;
				for (let i = 1; i <= segsN; i += 1) {
					const k = i / segsN;
					const jx = (Math.random() - .5) * 26 * (1 - Math.abs(k - .5) * 2 + .2);
					const jy = (Math.random() - .5) * 26 * (1 - Math.abs(k - .5) * 2 + .2);
					ctx.lineTo(state.ringX + (bx - state.ringX) * k + jx, state.ringY + (by - state.ringY) * k + jy);
				}
				ctx.stroke();
			}
			noGlow(ctx);
			ctx.globalAlpha = 1;
		}
		/**
		* 渲染一帧：背景、轨道、安全岛、终点、电环、闪电、粒子、红闪、震屏、
		* 进度条、HUD、遮罩。
		* @param ctx - 画布上下文。
		* @param state - 当前状态。
		* @param paused - 是否显示暂停遮罩。
		*/
		/**
		* 起点标记：发光圆圈 + 「起点」标签；就位阶段脉冲放大并附提示文案。
		*/
		function drawStart(ctx, state) {
			const start = {
				x: state.respawnX,
				y: state.respawnY
			};
			const pulse = state.armed ? 1 : 1 + .18 * Math.sin(state.t / 140);
			glow(ctx, START_COLOR, state.armed ? 8 : 16);
			ctx.strokeStyle = START_COLOR;
			ctx.lineWidth = 2.5;
			ctx.beginPath();
			ctx.arc(start.x, start.y, 14 * pulse, 0, Math.PI * 2);
			ctx.stroke();
			noGlow(ctx);
			ctx.fillStyle = START_COLOR;
			ctx.beginPath();
			ctx.arc(start.x, start.y, 3, 0, Math.PI * 2);
			ctx.fill();
			ctx.font = "600 12px system-ui, sans-serif";
			ctx.textAlign = "center";
			ctx.textBaseline = "top";
			ctx.fillText(state.checkpointTaken ? "重生点" : "起点", start.x, start.y + 20);
			if (!state.armed) {
				ctx.font = "700 16px system-ui, sans-serif";
				ctx.fillStyle = THEME.text;
				ctx.fillText(state.checkpointTaken ? "触电！把电环带回重生点" : "把电环移到起点开始", 320, 212);
				ctx.font = "600 12px system-ui, sans-serif";
				ctx.fillStyle = THEME.textMuted;
				ctx.fillText("就位后才开始计时与判定", 320, 236);
			}
		}
		function renderSteadyHand(ctx, state, paused) {
			drawCircuitBoard(ctx, state.t);
			let shakeX = 0, shakeY = 0;
			if (state.shakeMs > 0) {
				const k = state.shakeMs / 420;
				shakeX = Math.sin(state.t / 16) * 8 * k;
				shakeY = Math.cos(state.t / 21) * 5 * k;
			}
			ctx.save();
			ctx.translate(shakeX, shakeY);
			drawRail(ctx, state.track, state.t);
			drawIsland(ctx, state);
			drawStart(ctx, state);
			drawEnd(ctx, state.track, state.t);
			drawRing(ctx, state);
			for (const ev of state.events) if (ev.type === "shock") {
				particles.burst(ev.x, ev.y, THEME.bad, 24, 240);
				particles.burst(ev.x, ev.y, THEME.gold, 10, 160);
			} else if (ev.type === "armed") {
				const start = state.track.points[0];
				particles.burst(start.x, start.y, START_COLOR, 16, 160);
			} else if (ev.type === "checkpoint") particles.burst(state.track.checkpoint.x, state.track.checkpoint.y, ISLAND_COLOR, 14, 140);
			else if (ev.type === "clear") particles.burst(state.track.end.x, state.track.end.y, END_COLOR, 30, 260);
			else particles.burst(320, 220, THEME.gold, 40, 320);
			particles.tick(ctx, paused ? 0 : 16);
			drawLightning(ctx, state);
			ctx.restore();
			if (state.flashMs > 0) {
				ctx.fillStyle = "rgba(247,118,142," + (.32 * (state.flashMs / 380)).toFixed(3) + ")";
				ctx.fillRect(0, 0, 640, 440);
			}
			const barY = 424;
			const barW = 620;
			ctx.fillStyle = "rgba(226,226,238,0.12)";
			ctx.fillRect(10, barY, barW, 6);
			const grad = ctx.createLinearGradient(10, 0, 630, 0);
			grad.addColorStop(0, CURRENT_COLOR);
			grad.addColorStop(1, END_COLOR);
			ctx.fillStyle = grad;
			ctx.fillRect(10, barY, barW * state.progress, 6);
			ctx.font = "600 10px system-ui, sans-serif";
			ctx.textAlign = "left";
			ctx.fillStyle = THEME.textMuted;
			ctx.fillText("进度 " + Math.round(state.progress * 100) + "%", 10, 420);
			const hudY = 18;
			ctx.font = "600 13px system-ui, sans-serif";
			ctx.textAlign = "center";
			ctx.fillStyle = state.lives >= 1 ? THEME.bad : THEME.textMuted;
			ctx.fillText(state.lives >= 1 ? "❤".repeat(state.lives) : "♡", 40, hudY);
			hudPair(ctx, 90, hudY, "关卡", state.level + "/5");
			hudPair(ctx, 200, hudY, "用时", (state.levelMs / 1e3).toFixed(1) + "s");
			hudPair(ctx, 320, hudY, "最佳", state.bestMs === null ? "--" : (state.bestMs / 1e3).toFixed(1) + "s");
			ctx.font = "600 13px system-ui, sans-serif";
			ctx.textAlign = "right";
			ctx.fillStyle = THEME.text;
			ctx.fillText("分数 " + state.score, 630, hudY);
			if (paused) drawOverlay(ctx, 640, 440, "暂停", "按 P 继续 · R 重开");
			else if (state.over && state.complete) drawOverlay(ctx, 640, 440, "全部通关", state.score + " 分 · 最快 " + ((state.bestMs ?? 0) / 1e3).toFixed(1) + "s · 按 R 重开", END_COLOR);
			else if (state.over) drawOverlay(ctx, 640, 440, "游戏结束", "第 " + state.level + "/5 关 · " + state.score + " 分 · 按 R 重开", THEME.bad);
		}
		//#endregion
		//#region src/client/games/steadyhand/index.ts
		function createSteadyHandGame(host, options) {
			const canvas = document.createElement("canvas");
			canvas.className = "dmg-game-canvas";
			canvas.style.touchAction = "none";
			host.replaceChildren(canvas);
			const initialFit = fitCanvas(host, canvas, 640, 440);
			if (initialFit === null) throw new Error("dsh-minigames: steadyhand needs a 2d canvas context");
			const ctx = initialFit.ctx;
			const state = createSteadyHand(1);
			let paused = false;
			let lastScore = -1;
			const particles = createParticles();
			const toLogical = (event) => {
				const rect = canvas.getBoundingClientRect();
				return {
					x: (event.clientX - rect.left) * 640 / rect.width,
					y: (event.clientY - rect.top) * 440 / rect.height
				};
			};
			const reportScore = () => {
				if (state.score !== lastScore) {
					lastScore = state.score;
					options?.onScore?.(state.score);
				}
			};
			const onPointerMove = (event) => {
				const p = toLogical(event);
				if (!paused) setPointer(state, p.x, p.y);
			};
			const onKeyDown = (event) => {
				if (!gameHasFocus(host)) return;
				if (event.code === "KeyR") {
					event.preventDefault();
					const fresh = createSteadyHand(1, state.bestMs);
					Object.assign(state, fresh);
					lastScore = -1;
					loop.markDirty();
				} else if (event.code === "KeyP") {
					event.preventDefault();
					togglePause();
				}
			};
			const loop = createFrameLoop((f) => {
				if (!paused) {
					stepSteadyHand(state, f.dt * 1e3);
					for (const ev of state.events) if (ev.type === "shock") particles.burst(state.ringX, state.ringY, THEME.bad, 14, 180);
					else if (ev.type === "clear") {
						particles.burst(state.ringX, state.ringY, THEME.gold, 20, 200);
						reportScore();
					} else if (ev.type === "complete") reportScore();
					if (state.flashMs > 0 || state.shakeMs > 0 || particles.size() > 0) loop.markDirty();
				}
				renderSteadyHand(ctx, state, paused);
				particles.tick(ctx, f.dt * 1e3);
			});
			const pause = () => {
				if (paused) return;
				paused = true;
				loop.pause();
				renderSteadyHand(ctx, state, true);
			};
			const resume = () => {
				if (!paused) return;
				paused = false;
				loop.markDirty();
				loop.resume();
			};
			const togglePause = () => {
				if (paused) resume();
				else pause();
			};
			canvas.addEventListener("pointermove", onPointerMove);
			window.addEventListener("keydown", onKeyDown);
			focusGameHost(host);
			loop.start();
			return {
				start: resume,
				pause,
				resume,
				destroy: () => {
					loop.destroy();
					canvas.removeEventListener("pointermove", onPointerMove);
					window.removeEventListener("keydown", onKeyDown);
					initialFit.dispose();
				}
			};
		}
		const steadyhandGame = {
			id: "steadyhand",
			title: "电流急急棒 Steady Hand",
			icon: "⚡",
			description: "捏着电环走过弯曲金属轨——碰到就通电报警，手有多稳路有多长。",
			controls: [
				"移动指针带动电环（限速跟随）",
				"触电回检查点 -1 命（共 3 命）",
				"R：重开 · P：暂停 · 共 5 关"
			],
			create: createSteadyHandGame
		};
